const rows=[
 ['consciousness','01','意识层','选择创造的方向',[['身份','我是谁？我又选择成为谁？','选择愿意体现的品质与立场；身份可以发展，不把自己锁进标签。'],['信念','我把什么当作真实，它怎样塑造我的体验？','辨认关于自己、他人与世界的前提，也允许事实修正这些前提。'],['意图','此刻，我真正愿意创造什么？','把身份化为这一次选择的方向，分清真正在意的事与期待获得的认可。']]],
 ['template','02','模板层','让可能成为可体验的内在经验',[['想象','尚未发生的可能，我能怎样先去体验？','构造画面、情境与存在状态，让尚未发生的可能成为可以体验的回应。'],['聚焦','我把注意交给什么，又以怎样的方式投入？','让所选择的可能获得持续展开的空间；深入、回来，也为新的经验保留位置。'],['情绪','这份感受让我看见什么，我愿意怎样回应？','让经验有切身的分量，让回应有自己的选择；在理解与表达中认识自己。']]],
 ['reality','03','实相层','让选择进入日常生活',[['思维','我怎样把经验变成理解与判断？','通过提问、理解与推演形成认识，让判断与方案接受经验检验。'],['话语','我怎样表达自己，也让他人进入对话？','在说与写中理解自己，在倾听与回应中遇见他人，以表达、承诺和修正参与共同生活。'],['行动','我怎样实际参与，让选择成为生活？','以可观察的选择改变条件，让新经验有机会发生，再接受结果的检验。']]]
];
const triple=(items,cls='')=>`<div class="be-three ${cls}">${items.map(([title,body])=>`<div><h3>${title}</h3><p>${body}</p></div>`).join('')}</div>`;
function model(){return `<section class="be-section" id="be-model"><div class="be-section-head"><span class="eyebrow">01 / 三层九要素</span><h2>方向，内在经验，<br>生活中的落实。</h2></div><p class="be-lead">模板，是一个人对“将会发生什么、自己如何置身其中、怎样回应”的内在预演模式。它会被信念自动唤起，也能通过有意识的想象与实践逐渐改写。</p><div class="be-matrix">${rows.map(([id,n,title,sub,cells])=>`<section id="be-${id}" class="be-row"><div class="be-row-title"><span>${n}</span><h3>${title}</h3><p>${sub}</p></div><div class="be-cells">${cells.map(([name,q,desc])=>`<div><h4>${name}</h4><p class="be-question">${q}</p><p>${desc}</p>${name==='想象'?'<button class="text-link" data-be-open="practice">展开想象三层 ↗</button>':''}</div>`).join('')}</div></section>`).join('')}</div><div class="be-reading prose"><p>“主动”与“自动”描述模板形成的两种方式，不增加新的层级。“深层信念”指那些熟悉、常被当作事实而不易察觉的前提，未必都藏在不可接近的潜意识里。</p><p>九要素是《三道哲学》借鉴赛斯、细雨及相关思想重构的实践模型，并非赛斯本人提出的固定三分法。这里的“实相层”指日常落实的入口：思维是其中的组织活动，不意味着一切思维都发生在想象之后，更不把外部世界归结为个人的心理产物。</p><p>以“想象 → 聚焦 → 情绪”作为讲解顺序：先展开可能，再投入注意，进而感受它的意义。真实经验会往复：情绪也会唤起画面，聚焦会改变想象，行动还能先于心境的转变。九要素是分工图，不是必须逐格执行的流水线。</p><p>生命蓝图保留为意识层背后的哲学背景，连接天道的多维自我与可能性；当下意图体现此刻的自由选择。<a class="source-link" href="#/concept/blueprint">阅读生命蓝图 ↗</a></p></div></section>
<section class="be-section" id="be-loop"><div class="be-section-head"><span class="eyebrow">02 / 经验的回路</span><h2>信念塑造体验。<br>体验，也能更新信念。</h2></div><p class="be-lead">信念 → 想象 → 情绪 → 体验 → 强化或修正信念。聚焦选择进入视野的线索，思维、话语与行动参与体验的形成；环境、他人与偶然事件也持续进入这个回路。</p><div class="be-switch" role="group" aria-label="比较两种经验回路"><button data-loop="automatic" aria-pressed="true">自动强化</button><button data-loop="chosen" aria-pressed="false">觉察与修正</button></div><div id="be-loop-content" aria-live="polite"></div><p class="be-small">这是用于自我观察的简化模型，箭头表示可能的影响路径，不代表固定因果、必然结果或经过验证的完整心理学定律。</p>${triple([['觉知 · 多出一点空间','认出“我正在经历一个念头或画面”。它是当下的心理事件，不必立即当作事实。'],['觉察 · 看清具体构造','分别辨认触发、身体感受、信念、想象与反应；询问自己正在保护什么，事实支持到哪里。'],['重新选择 · 回到可做的一步','从珍视的品质出发，选择一句话或一个行动；回看结果，允许更新原来的解释。']])}<p class="be-small">这三步是贯穿回路的操作提示，与“认识自己—接纳自己—创造自己”相连，不替换“三觉”的概念定义。</p><a class="text-link" href="#/awareness">进入觉察训练 ↗</a></section>
<section class="be-section" id="be-conflict"><div class="be-section-head"><span class="eyebrow">03 / 当两种模板冲突</span><h2>谁在主导，<br>取决于此刻怎样回应。</h2></div><div class="be-reading prose"><p><strong>短时反应中，熟悉的自动模式可能先占上风；长期走向上，有意识的选择可以通过练习、环境支持与新的经验，逐渐改变默认回应。</strong>这是一种实践解释，不是“潜意识永远战胜意识”的定律，也没有一个隐藏的主体在背后决定全部人生。</p><p>需要先分清“主导什么”。身体的第一波紧张、对事件的解释、接下来的一句话，以及外部最终结果，是四件不同的事。你可能仍然害怕，却已经选择不攻击对方；新的行动先出现，情绪的信任稍后才跟上。外部结果还取决于资源、能力、他人的意愿与客观条件。</p></div>${triple([['旧模式为何先出现','它与熟悉的线索、过去的经验及保护需要相连。在某些实验任务中，压力使行为更偏向习惯。把这一发现推广到复杂人生情境仍需谨慎。'],['新选择为何暂时站不稳','口头愿望可能缺少可信经验，也可能与其他需要冲突：“我想表达”与“我想避免被否定”可以同时存在。另一些阻力来自真实的技能或环境限制。'],['转化如何逐渐发生','把新身份落实为小而可信的回应，预演困难，调整条件，再让事实校准预期。保留旧模式要保护的需要，为它发展更合适的实现方式。']])}<p class="be-small">压力与习惯的实验依据：${source(sources.habit,'Schwabe & Wolf，2009')}。本页“自动模板”的含义比实验中的习惯行为更宽，两者不能直接等同。</p><div class="be-reading prose"><h3>先理解冲突保护了什么。</h3><p>例如，“我想成为负责的领袖”与“只要被质疑就证明我不配”相遇时，漂亮的成功画面很容易被现实中的批评打断。可以先把旧信念写成条件句：“如果我承认不知道，别人就会抛弃我。”再把新选择降到可信的尺度：“我可以承认一处不知道，并把问题带到下一步。”</p><p>预演时加入那一句真实的批评。感受胸口紧张，允许它存在，再练习回应：“这点我需要核实，我会在明天下午反馈。”Being 就在这个愿意承担、保持诚实、允许自己学习的姿态里，而不只在受到敬仰的形象里。</p><h3>让事实改变下一次的预期。</h3><p>实践前记下预测；实践后区分实际发生、自己的解释和仍不知道的部分。若结果与预期不同，既记录新的证据，也检查技能、时机、资源与关系边界。不要把一次成功当作全能证明，也不要把失败解释成“我内心不够相信”。信念的修正可以是“有些场合能安全表达，我可以逐步辨别”，不必骤变成“所有人都会支持我”。</p><p>转化的标志是选择空间扩大：更早认出模式，更能容纳情绪，更能做出合适回应，也更愿意依据事实修正自己。旧反应偶尔返回，不取消已经发生的成长。</p><h3>放回赛斯的语境，答案还要再深一层。</h3><p>在1978年10月11日的私人课中，赛斯讨论了意志与想象的表面冲突，把关注点转向真实欲求与动机，而非简单宣布想象总会获胜。据此，我们可以追问：我公开宣称的目标，是否容纳了自己尚未承认的愿望？这是对该段的哲学解读，不能当作临床诊断或外部事件的因果证明。${source(sources.motives,'查看对应英文节次')}</p><p>在三道哲学中，我们把转化理解为：看见各自的需要，选择愿意承担的方向，让想象、情绪、表达与行动逐渐协调。并非要先清除所有矛盾，人才有资格开始创造。</p></div><button class="button" data-be-open="practice">把理解带入一次练习 ↗</button></section>`;}
const prompts=[
 ['定向','先认识当下，再选择方向。',[
 ['facts','看清处境','发生了什么？哪些是事实，哪些是我的推断？','例如：同事说方案缺少依据。我推断他看不起我。'],
 ['need','理解旧模板','最先出现的画面或条件句是什么？它在保护什么需要？','如果我承认不知道，就会……我正在保护……'],
 ['identity','选择身份与意图','此刻愿意体现哪一种品质？只选自己能承担的部分。','我愿意成为诚实而能承担的人。这次先把问题问清。']]],
 ['入境','用画面、体验和 Being 预演一次回应。',[
 ['picture','画面 · 选一个片刻','选择接下来可能遇见的日常片刻；给它一个具体背景。','明天下午的讨论桌旁，对方提出了一个尖锐的问题。'],
 ['scene','情境 · 加入真实阻力','让情境展开：听到什么、身体怎样反应、第一步怎样做？','我感到紧张，先停一下，听完问题，再确认对方的意思。'],
 ['being','Being · 从身份内部回应','暂时以这个品质已经可被活出的状态参与：如何呼吸、说话、守边界、承担后果？','我可以紧张，也可以诚实。我不急着证明所有答案都在我这里。']]],
 ['落实','让想象与真实经验彼此校准。',[
 ['obstacle','辨认障碍','回到当下：哪一点还不可信？需要哪些能力、资源或支持？','我还不熟悉数据，提前查清一处事实；不要求自己瞬间从容。'],
 ['action','小步行动','如果出现一个具体触发，我就做什么？何时尝试、何时回看？','如果想立刻反驳，我先问一个澄清问题。明晚回看事实。'],
 ['review','接纳反馈','原先预测是什么？实际发生什么？信念应保留、缩小还是修正？','事实……我的解释……还不知道……下一次的调整……']]]
];
function practice(){return `<section class="be-section"><div class="be-section-head"><span class="eyebrow">想象 / 三种深度</span><h2>看见那个可能。<br>也体验怎样活出它。</h2></div><p class="be-lead">在这里，visualization 指内在预演。画面鲜明并非前提；也可以借助声音、语言、身体姿态或对情境的理解。三层可以交织，不是想象能力的等级考试。</p>${triple([['01 · 画面','看见一个期望中的片刻。例如，自己站在讲台上完成一次分享。画面帮助方向具体，但还没有回答怎样面对过程。'],['02 · 情境体验','走进那个片刻，感受声音、身体、关系与时间的展开。例如，听到提问，感到紧张，仍能倾听、思考和回应。'],['03 · Being 状态','暂时从“所选择的品质已经可以被活出”的位置体验自己。面对压力、批评与不确定，怎样承担、诚实、关怀与设定边界？']],'be-depths')}<div class="be-reading prose"><p><strong>“已实现身份”是一种当下的体验姿态。</strong>它不要求你相信外部目标已经完成。可以预演“我正在以一个负责的人的方式回应”，同时清楚能力还在发展、结果尚未确定。责任、诚实与勇气可以当下体现；职位、收入或他人的认可需要现实条件。</p><p>身份回答“我选择成为谁”，Being 想象回答“我如何从这个身份内部体验并回应”。两者连接意识层与模板层。此三层划分是本体系的教学设计，尚不是经过整体验证的心理学分级。</p></div></section>
<section class="be-section" id="be-exercise"><div class="be-section-head"><span class="eyebrow">VISUALIZATION / 三段九步</span><h2>定向 · 入境 · 落实</h2></div><p class="be-lead">从一件小事开始，花几分钟即可。可以先选一个问题，也可以回到前一步；无需完成全部九格。找不到感受时，只写一句话或做一个动作，也算开始。</p><div class="be-gentle"><p>先感觉脚下的支撑，保持自然呼吸。让感受如实出现，不强迫兴奋、不赶走所有担忧。若预演使你明显不适，睁眼回到周围环境，缩小情境或暂停练习。目的在于增加选择空间。</p></div><form id="be-form">${prompts.map(([title,desc,fields],j)=>`<fieldset class="be-practice-stage"><legend><span>0${j+1}</span>${title}</legend><p>${desc}</p><div class="be-fields">${fields.map(([id,label,help,placeholder],i)=>`<div><label for="be-${id}"><span>0${j*3+i+1}</span>${label}</label><p id="be-${id}-help">${help}</p><textarea id="be-${id}" name="${id}" aria-describedby="be-${id}-help" placeholder="${placeholder}" rows="4"></textarea></div>`).join('')}</div></fieldset>`).join('')}<div class="be-form-actions"><button type="button" class="button" id="be-export">导出本次练习 ↓</button><button type="button" class="plain-button" id="be-clear">清空这份记录</button><p id="be-save" role="status">记录仅保存在当前浏览器，不会提交到服务器。</p></div></form><div class="be-reading prose"><h3>每次回看，只抓住一个变化。</h3><p>我是否更早认出了旧模式？是否在有情绪时做出了一次新回应？结果给了我什么支持或反证？把练习接回真实互动，并据此调整下一次预演。允许方向保持稳定，具体画面、节奏与策略继续生长。</p><p>这里推荐加入过程与阻力，有一部分来自心理预演研究：一项大学生备考实验发现，预演学习过程改善了学习与成绩，规划和焦虑变化参与其中；这不证明任何一种想象在所有领域都有效。${source(sources.process,'Pham & Taylor，1999')}</p><p>对理想结局的沉浸也可能带来提前满足。Kappes 与 Oettingen 的实验观察到，某些理想化的积极幻想降低了后续动员程度。我们因此把愿景接回障碍与行动，而不把情绪越强、画面越美当作效果指标。${source(sources.fantasy,'Kappes & Oettingen，2011')}</p><p class="be-small">三段九步是基于上述研究与本体系目标提出的整合练习，整体流程尚未经独立验证；它不承诺指定结果或替代技能训练。</p></div></section>`;}
function cases(){return `<section class="be-section"><div class="be-section-head"><span class="eyebrow">案例 / 模板如何被共同维持</span><h2>当“万一”成为<br>一家人的默认语言。</h2></div><div class="be-reading prose"><p>在用户提供的《[Y9-4] 已知的实相IX》第475节摘录中，细雨描绘了一对不断预演坏结果的夫妻。他们相互确认忧虑，把自己的应对解释为先见之明，再将这套习惯作为生活经验传给孩子。</p><p>可以用模板层来读这个例子：不安全的前提唤起灾难画面，注意反复停留在危险，情绪推动防御；双方的言语又使同一种解释越来越像常识。此处的心理与关系分析是我们的解读，并非该案例已经被实验验证。</p><p>关键在于：<strong>“我们做过准备”不等于“持续担忧是避免灾难的必要条件”。</strong>若坏事没有发生，不能直接断定是担忧阻止了它；若发生了，也不能断定是担忧创造了它。持续焦虑与风险本身要分别辨认。</p></div>${triple([['信念 · 什么被当成真理','“不不断想最坏的情况，就是不负责任。”两人因此把警惕与关心绑在一起。'],['模板 · 什么反复被预演','坏结果在想象中越来越具体，聚焦持续搜索威胁，情绪又让这些画面显得更可信。'],['实相 · 什么进入了关系','反复提醒、确认和防御可能改变交流方式；回看时若只留下支持旧判断的部分，信念便继续强化。']])}<div class="be-reading prose"><h3>同样关心安全，也能选择另一种共同实践。</h3><p>先分别说出担忧与需要，不把一方标成“负能量的人”。一起列出确有依据的风险，约定一次足够的准备、明确的行动和重新评估时间。完成准备后，把注意还给共同生活；发现新证据时再调整。若存在真实的伤害、资源困境或边界问题，应直接处理这些条件。</p><p>建设性预案会产生可用的决策，并有停止条件；灾难性反刍常常只是重复同一个威胁而没有增加行动信息。这一区分是本页的实用判断提示，不是凭一段表现对人作诊断。</p><h3>第478节：把可能性与事实分开。</h3><p>用户提供的线索指出，细雨在第478节用异地男友的例子，讨论积极与消极想象。由于尚未取得对应中文页，本页不补写故事细节，也不把它列为赛斯的原例。用于练习时，我们可以另设情境：对方暂时没有回复，分别写下事实、脑中剧情与可核实的问题，再选择合宜的沟通。</p><p>已核对的赛斯第478节英文摘录则涉及对恐惧本身的害怕，以及交流、安慰与重新转移关注。本页据此提醒：察觉到负面念头后，不必增加“这个念头会造成灾祸”的第二层恐惧。其关于心理力量的更广泛解释仍属于赛斯的思想语境。${source(sources.seth478,'第478节英文摘录')}</p></div><button class="button" data-be-open="practice">以一次真实互动开始 ↗</button></section>
<section class="be-section" id="be-sources"><div class="be-section-head"><span class="eyebrow">来源 / 解释的边界</span><h2>让每一种说法，<br>回到它自己的依据。</h2></div><div class="be-source-list">
<details><summary>赛斯文本 · 已核对到哪里？</summary><div class="prose"><p>第475节：英文检索页标为《The Personal Sessions》Book 1，1969年4月14日。可核对到一方的积极改变被另一方的沮丧或消极模式抵消的叙述。用户引用的“七倍”段落尚未逐句核对，不作为计算式或科学结论。${source(sources.seth475,'查看含第475节的英文摘录')}</p><p>第478节：同书，1969年4月28日。可核对“对恐惧的恐惧”、交流与关注方向的相关段落。${source(sources.seth478,'查看英文摘录')}</p><p>1978年10月11日私人课：涉及意志、想象与真实动机。此处按英文检索摘录转述，未对照纸本页码。${source(sources.motives,'查看英文节次')}</p><p>英文检索页是文本检索渠道，引用的是其中标识的赛斯段落；中文编译、解释与英文原文的边界仍应分别核对。</p></div></details>
<details><summary>细雨评论 · 夫妻与异地男友案例</summary><div class="prose"><p>中文定位由用户提供：《[Y9-4] 已知的实相IX》，第475节，册内约172页；第478节。夫妻故事在提供的上下文中明确属于细雨的注释或解读，因此本页将其标为细雨案例，不归为赛斯原话。第478节的“异地男友”仅有用户提供的出处线索，尚未独立核对正文。</p><p>细雨社的《私人课合辑》出版说明确认：Y系列收录了相关私人课，并将赛斯资料与细雨文字并列呈现。这个说明支持区分作者层次，但本身不能完成上述两个案例的逐句核验。${source(sources.xiyu,'细雨社出版说明')} ${source(sources.y9,'Y9-4书目页')}</p><p>Y8-1、Y8-4的同主题线索暂不扩展引文，待取得对应页后再校勘。页码会随版本变化，节次应优先保留。</p></div></details>
<details><summary>心理学依据 · 支持什么，不支持什么？</summary><div class="prose"><p>Holmes 与 Mathews（2005）：实验中的不愉快意象比对同一材料的语言加工引起更强的焦虑变化。这支持想象会影响情绪的部分，不能证明担忧使外部灾难发生。${source(sources.imagery,'原始研究摘要')}</p><p>Pham 与 Taylor（1999）：在备考情境中，过程预演有助于规划、学习及表现。${source(sources.process,'原始论文')}</p><p>Kappes 与 Oettingen（2011）：理想化的积极幻想在部分实验条件下会降低动员程度，不能把积极想象一概视为促进表现。${source(sources.fantasy,'原始论文')}</p><p>Schwabe 与 Wolf（2009）：特定实验任务中，压力使控制更偏向习惯。它为理解自动反应提供有限参照，不能证明所有深层信念支配全部行动。${source(sources.habit,'原始研究摘要')}</p><p>本页的完整闭环、Being三层及三段九步练习，是《三道哲学》的整合设计。已有研究支持其中某些环节，不等于验证整套模型。</p></div></details>
<details><summary>形而上学主张 · 作为世界观讨论</summary><div class="prose"><p>在赛斯与细雨的思想语境中，意识、信念、想象与情感被赋予更广泛的实相创造作用。将内在活动直接视为外部物质事件的生成原因，以及“七倍”“坍缩成事实”等说法，不能由上述心理学研究推出，也不作为本页已经成立的科学机制。</p><p>困境可能来自他人行为、社会条件、资源与偶然事件。经历困境的人不应因此被归咎为想错、怕错或信得不够。情绪是需要理解的经验，不是道德考核，也不是预测灾祸的指标。</p></div></details></div></section>`;}
const beEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const loops={automatic:[['信念','“被质疑就说明我不够好。”'],['想象','预演所有人都在否定自己。'],['情绪','羞耻、紧张与防御冲动。'],['体验','急着辩解，交流收缩；更容易忽略支持。'],['强化','只记住冲突：“果然不能暴露不足。”']],chosen:[['信念','“被质疑时，我仍能学习并承担。”'],['想象','预演听完问题，再回应一个具体事实。'],['情绪','允许紧张，同时保留好奇与稳定。'],['体验','先澄清、再行动，观察双方实际反应。'],['修正','记录支持与反证，调整下一次的预期。']]};
const beCrumbs=practice=>`<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a><span>/</span><a href="#/ren">人道</a><span>/</span>${practice?'<a href="#/becoming">创造自己</a><span>/</span><span aria-current="page">九项实践</span>':'<span aria-current="page">创造自己</span>'}</nav>`;
function layerRelations(layer){return `<div class="be-relation-flow">${layer.roles.map((role,i)=>`<span>${role}</span>${i<2?'<b aria-hidden="true">↔</b>':''}`).join('')}</div><div class="be-relation-pairs">${layer.pairs.map(([title,body])=>`<div><h3>${title}</h3><p>${body}</p></div>`).join('')}</div><div class="be-layer-result"><h3>共同作用</h3><p>${layer.result}</p></div><p class="be-layer-example"><span>放进一个情境</span>${layer.example}</p>${layer.id==='template'?'<div class="be-related"><a href="#/becoming/mechanism">深入：创造闭环与模板冲突 ↗</a><a href="#/becoming/cases">案例与来源 ↗</a></div>':''}`;}
export function becomingPage(){return creationOverviewPage();}
export function becomingElementPage(id){const imagined=practice();const exercise=imagined.slice(imagined.indexOf('<section class="be-section" id="be-exercise">'));return creationElementPage(id,id==='imagination'?`<details class="be-visualization-fold"><summary>展开详细预演记录 · 定向、入境、落实</summary>${exercise}</details>`:'');}
export function becomingReadingPage(kind){return kind==='cases'?creationSourcesPage():creationCyclePage();}
function bindBeRecord(root,{formId,key,fields,prefix,title}){
 const form=root.querySelector('#'+formId),status=root.querySelector('#'+prefix+'-save');let armed=false;
 const clear=root.querySelector('#'+prefix+'-clear');const clearText=clear.textContent;
 try{const record=JSON.parse(localStorage.getItem(key)||'{}');let restored=false;fields.forEach(([id])=>{if(typeof record[id]==='string'){form.elements[id].value=record[id];restored=restored||!!record[id];}});if(restored)status.textContent='已恢复当前浏览器中的练习记录。';}catch{status.textContent='浏览器暂时无法恢复记录；可以填写后导出。';}
 const values=()=>Object.fromEntries(fields.map(([id])=>[id,form.elements[id].value]));
 form.onsubmit=ev=>ev.preventDefault();form.addEventListener('input',()=>{armed=false;clear.textContent=clearText;try{localStorage.setItem(key,JSON.stringify(values()));status.textContent='已保存在当前浏览器，不会提交到服务器。';}catch{status.textContent='浏览器无法保存，请导出本次练习。';}});
 root.querySelector('#'+prefix+'-export').onclick=()=>{const v=values();if(!Object.values(v).some(x=>x.trim())){status.textContent='写下一句话后，就可以导出本次练习。';return;}const content='三道哲学 · '+title+'\n\n'+fields.map(([id,label])=>label+'\n'+(v[id]||'（未填写）')).join('\n\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='三道哲学-'+title+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='练习已导出。';};
 clear.onclick=()=>{if(!armed){armed=true;clear.textContent='确认清空？';status.textContent='再次点击将清空这份练习，其他练习的记录不受影响。';return;}form.reset();let cleared=true;try{localStorage.removeItem(key);}catch{cleared=false;}armed=false;clear.textContent=clearText;status.textContent=cleared?'这份练习已清空。':'页面已清空，但浏览器中的旧记录未能移除。';form.dispatchEvent(new Event('recordclear'));};return values;
}
export function initBecoming(params){
 const root=document.querySelector('.becoming-page');if(!root)return;
 root.querySelectorAll('.action-sources,.identity-sources').forEach(d=>d.open=false);
 const old=params.get('tab'),topic=params.get('topic')||(old==='practice'?'imagination':old==='cases'?'cases':null);
 if(root.classList.contains('be-framework')&&topic){location.replace('#/becoming/'+({loop:'mechanism',conflict:'mechanism',cases:'cases',imagination:'imagination'}[topic]||'imagination'));return;}
 root.querySelectorAll('.be-layer-fold').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('.be-expand-label').innerHTML=d.open?'收起 <b>−</b>':'展开 <b>＋';}));
 const layer=params.get('layer');if(['consciousness','template','reality'].includes(layer)){const d=root.querySelector('#be-'+layer+'>details');if(d){d.open=true;requestAnimationFrame(()=>d.scrollIntoView({block:'start',behavior:'instant'}));}}
 root.querySelectorAll('[data-be-open]').forEach(b=>b.onclick=()=>{location.hash='#/becoming/practice';});
 function setLoop(id){root.querySelectorAll('[data-loop]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.loop===id)));root.querySelector('#be-loop-content').innerHTML=`<ol class="be-loop">${loops[id].map(([t,p])=>`<li><h3>${t}</h3><p>${p}</p></li>`).join('')}</ol><p class="be-loop-return">↶ 体验的解释回到信念，参与下一轮预演</p>`;}
 if(root.querySelector('#be-loop-content')){root.querySelectorAll('[data-loop]').forEach(b=>b.onclick=()=>setLoop(b.dataset.loop));setLoop('automatic');}
 if(root.querySelector('#be-form'))bindBeRecord(root,{formId:'be-form',key:'triatao.becoming.practice.v1',fields:prompts.flatMap(p=>p[2]),prefix:'be',title:'想象练习'});
 root.querySelectorAll('[data-element-anchor]').forEach(b=>b.onclick=()=>{const target=root.querySelector('#'+b.dataset.elementAnchor);if(!target)return;if(['action-sources','belief-sources','identity-sources','intention-sources','imagination-sources','focus-sources','emotion-sources','thinking-sources','words-sources'].includes(target.id))target.querySelector('details').open=true;target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});target.tabIndex=-1;target.focus({preventScroll:true});});
}
const nine=[
 ['identity','身份','我怎样认识自己，又选择成为谁？','围绕同一件事写三句话：我以为自己是……；这次体验让我看见……（区分事实、感受与解释）；接下来我选择活出……（一种品质及一个可承担的行动）。保留起点，也为未尝试的可能留空间。','我以为：我不会表达。体验：会议中紧张，之后却能向同事问清问题。新认识：有准备、能暂停时，我更能表达。我选择：求真与担当；下次先准备并提出一个关键问题。'],
 ['belief','信念','哪些前提正在影响我，它们经得起检验吗？','写下具体情境与候选前提，列出支持、反例和其他解释；选择更准确的新理解与一个小行动，实践后分别记录内在变化和实际结果。','情境：明天需要回应质疑。候选前提：承认不知道就会被否定。支持：曾被讥讽。反例：也曾请教后得到帮助。其他解释：这次准备不足。新理解：可靠包括诚实核实。小行动：先确认一个关键数据，再约定反馈。'],
 ['intention','意图','这一次，我真正愿意创造什么？','写清这次愿意活出的品质、创造方向与可承担的投入。需要时，回看自己的身份理解与信念前提。区分自己的部分、需共同协商的部分，再约定何时根据体验回看。','这次我愿意以诚实与担当，把风险说清。我会准备关键事实、听取团队意见，讨论可行的下一步；会后回看实际回应，再调整。'],
 ['imagination','想象','如果活出这个身份，我会怎样回应？','用画面、声音、语言或对情境的理解，进入一个具体片刻。从所选择的品质出发，预演遇到变化时怎样回应，再记下需要落实或确认的一步。','对方提出批评。我听完，感到紧张，却仍愿意认真追问具体依据。'],
 ['focus','聚焦','这一次，我愿意把注意交给什么？','选定关注的对象与方式，安排一段投入和适合的回看时点。偏离时，从可接续的地方回来。','带着好奇听清对方的问题；谈完再记录发现，约定需要跟进的事。'],
 ['emotion','情绪','这份感受让我看见了什么，我愿意怎样回应？','承认此刻的体验，分清事实与解释。了解在意与需要，选择一次照顾或回应，也允许暂时不知道。','被质疑时有些紧张，我很在意这份工作。先听清具体问题，再说明已知与待确认的部分。'],
 ['thinking','思维','我正在怎样理解这件事，还有什么值得重新看见？','把问题写清，区分已有信息、解释与未知。选择一次了解、尝试、决定或暂缓，再让实际回应参与下一轮理解。','我想了解……目前知道……我的解释是……还需要确认……接下来我选择……哪些回应会使我重新考虑……'],
 ['words','话语','我愿意怎样说，也愿意怎样听？','选择一次表达、书写、感谢、请求或承诺。说清真正想被理解的内容，给回应留下位置，再跟进实际需要承担的部分。','我想表达……事实是……我感到／需要……我希望了解对方……接下来愿意回应……'],
 ['action','行动','现在可以迈出的具体一步是什么？','行动前：写清所选品质、阻力与具体一步。行动中：约定时机、完成尺度与遇阻的调整。行动后：记录事实、领悟与下一次选择。','如果我想急着反驳，就先问一个澄清问题。明天下午完成核对，晚间回看实际反应。']
];
export function ninePracticePage(){return `<div class="page-shell becoming-page be-nine-page">${beCrumbs(true)}<header class="be-framework-head"><p class="eyebrow">创造自己 / 九项实践</p><h1>从一个真实处境，<br>走向一次有意识的创造。</h1><p>从眼前最能参与的一项开始。记录方向、准备与实际行动，再用事实回看选择一致性和修正空间；其他项目可以留白。</p></header><form id="nine-form"><div class="nine-context"><label for="nine-context">今天想带入的处境</label><textarea name="context" id="nine-context" rows="2" placeholder="例如：明天我要回应一次尖锐的质疑……"></textarea></div><div class="nine-workspace"><nav class="nine-nav" aria-label="九项练习入口">${rows.map((row,g)=>`<div><p>${row[2]}</p><div>${nine.slice(g*3,g*3+3).map(([id,name],i)=>`<button type="button" data-nine-step="${g*3+i}" aria-controls="nine-panel-${g*3+i}" ${g+i===0?'aria-current="step"':''}><span>0${g*3+i+1}</span>${name}</button>`).join('')}</div></div>`).join('')}</nav><div class="nine-stage">${nine.map(([id,name,q,help,placeholder],i)=>`<section id="nine-panel-${i}" class="nine-panel" ${i?'hidden':''} aria-labelledby="nine-heading-${i}"><span class="eyebrow">${rows[Math.floor(i/3)][2]} / 0${i+1}</span><h2 id="nine-heading-${i}">${name}</h2><label for="nine-${id}">${q}</label><p id="nine-help-${id}">${help}</p><textarea name="${id}" id="nine-${id}" aria-describedby="nine-help-${id}" rows="7" placeholder="${placeholder}"></textarea>${id==='action'?'<a class="source-link" href="#/becoming/action">需要提示？回看实践、反馈与再次选择 ↗</a>':''}${id==='imagination'?'<a class="source-link" href="#/becoming/imagination">需要提示？回看画面、情境与 Being ↗</a>':''}${id==='belief'?'<a class="source-link" href="#/becoming/belief">需要提示？回看信念识别与小步实践 ↗</a>':''}${id==='identity'?'<a class="source-link" href="#/becoming/identity">需要提示？回看身份的三个核心问题 ↗</a>':''}${id==='thinking'?'<a class="source-link" href="#/becoming/thinking">需要提示？回看提问、理解与判断 ↗</a>':''}${id==='words'?'<a class="source-link" href="#/becoming/words">需要提示？回看表达、倾听与承诺 ↗</a>':''}${id==='intention'?'<a class="source-link" href="#/becoming/intention">需要提示？回看方向、承诺与校准 ↗</a>':''}</section>`).join('')}<div class="nine-step-actions"><button type="button" id="nine-prev" class="plain-button">← 上一项</button><span id="nine-position" role="status">当前：身份（1 / 9）</span><button type="button" id="nine-next" class="button">下一项 →</button></div></div></div><section id="nine-review" class="nine-review" hidden><span class="eyebrow">让体验回到信念</span><h2>回看这一次选择。</h2><div id="nine-summary"></div><label for="nine-feedback">实践之后，实际发生了什么？</label><p>分别记下原先预测、实际行为、可确认的结果与仍未知的部分。行为是否体现所选价值？面对不符预期的反馈，哪些理解、方法或环境条件需要修正？约定下一次尝试与回看时间。</p><textarea name="feedback" id="nine-feedback" rows="5" placeholder="原先预测……实际行为与结果……与价值一致的部分……需要修正的部分……下一步与回看时间……"></textarea><button type="button" id="nine-back" class="text-link">回到各项，继续调整 ↑</button></section><div class="be-form-actions nine-record-actions"><button type="button" id="nine-review-open" class="text-link">回看九项 ↗</button><button type="button" id="nine-export" class="plain-button">导出练习 ↓</button><button type="button" id="nine-clear" class="plain-button">清空这份记录</button><p id="nine-save" role="status">记录仅保存在当前浏览器，不会提交到服务器。</p></div></form><p class="be-small nine-boundary">这份记录用于理解一次选择，不是九项考核。身体、环境、资源和他人的选择同样影响结果。可以从任意一项进入，也可以带着实践反馈重新认识身份、信念与意图。</p><a class="text-link" href="#/becoming">返回创造自己 ↗</a></div>`;}
export function initNinePractice(params=new URLSearchParams()){
 const root=document.querySelector('.be-nine-page');if(!root)return;
 const fields=[['context','真实处境'],...nine.map(([id,name],i)=>[id,`0${i+1} ${name}`]),['feedback','实践后的反馈']];
 const values=bindBeRecord(root,{formId:'nine-form',key:'triatao.becoming.nine.v1',fields,prefix:'nine',title:'九项实践'});
 let current=0;const panels=[...root.querySelectorAll('.nine-panel')],nav=[...root.querySelectorAll('[data-nine-step]')],next=root.querySelector('#nine-next'),previous=root.querySelector('#nine-prev'),review=root.querySelector('#nine-review');
 function show(index,focus=false){current=Math.max(0,Math.min(8,index));panels.forEach((p,i)=>p.hidden=i!==current);nav.forEach((b,i)=>{if(i===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});previous.disabled=current===0;next.textContent=current===8?'回看九项 ↗':'下一项 →';root.querySelector('#nine-position').textContent=`当前：${nine[current][1]}（${current+1} / 9）`;if(focus){panels[current].querySelector('textarea').focus({preventScroll:true});root.querySelector('.nine-stage').scrollIntoView({block:'start',behavior:'instant'});}}
 function summary(){const v=values();root.querySelector('#nine-summary').innerHTML=`<p class="nine-summary-context">${beEsc(v.context||'从一件真实的事开始。')}</p><div class="nine-summary-grid">${nine.map(([id,name])=>`<div><h3>${name}</h3><p>${beEsc(v[id]||'暂未填写，留待继续探索。').replace(/\n/g,'<br>')}</p></div>`).join('')}</div>`;}
 function openReview(){summary();review.hidden=false;review.scrollIntoView({block:'start',behavior:'instant'});root.querySelector('#nine-feedback').focus({preventScroll:true});}
 nav.forEach(b=>b.onclick=()=>show(Number(b.dataset.nineStep),true));previous.onclick=()=>show(current-1,true);next.onclick=()=>current===8?openReview():show(current+1,true);root.querySelector('#nine-review-open').onclick=openReview;root.querySelector('#nine-back').onclick=()=>show(current,true);
 root.querySelector('#nine-form').addEventListener('input',()=>{if(!review.hidden)summary();});root.querySelector('#nine-form').addEventListener('recordclear',()=>{review.hidden=true;show(0);});show(Math.max(0,nine.findIndex(x=>x[0]===params.get('step'))));
}
